cat > /tmp/verify_and_push.mjs << 'SCRIPT'
const TOKEN = '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';
const REPO = 'ibb142/ivx-holdings-platform';

// 1. Verify token
const userRes = await fetch('https://api.github.com/user', {
  headers: { Authorization: `token ${TOKEN}` },
});
const userData = await userRes.json();
console.log(`Token valid: ${userRes.ok} login=${userData.login || userData.message}`);

if (!userRes.ok) process.exit(1);

// 2. Check current GitHub main SHA
const branchRes = await fetch(`https://api.github.com/repos/${REPO}/branches/main`, {
  headers: { Authorization: `token ${TOKEN}` },
});
const branchData = await branchRes.json();
console.log(`GitHub main SHA: ${branchData.commit?.sha ?? branchData.message}`);

// 3. Check local HEAD
const { execSync } = await import('child_process');
const localHead = execSync('git rev-parse HEAD', { cwd: '/home/user/rork-app', encoding: 'utf-8' }).trim();
console.log(`Local HEAD: ${localHead}`);
SCRIPT
bun /tmp/verify_and_push.mjs

